def normalize_line_endings(text):
    import re
    return re.sub(r'\r\n|\r', '\n', text)

def format_initials_from_email(email):
    local = email.split('@', 1)[0]
    parts = local.split('.')
    return ''.join(p[0].upper() for p in parts if p)

def format_range(start, end):
    if start == end:
        return str(start)
    return f'{start}-{end}'

def expand_month(abbr):
    months = {'jan': 'January', 'feb': 'February', 'mar': 'March', 'apr': 'April',
              'may': 'May', 'jun': 'June', 'jul': 'July', 'aug': 'August',
              'sep': 'September', 'oct': 'October', 'nov': 'November', 'dec': 'December'}
    key = abbr.lower()
    return months.get(key, abbr)

def format_fraction_as_mixed(numerator, denominator):
    from math import gcd
    whole = numerator // denominator
    remainder = numerator % denominator
    if remainder == 0:
        return str(whole)
    g = gcd(remainder, denominator)
    a = remainder // g
    b = denominator // g
    if whole == 0:
        return f'{a}/{b}'
    return f'{whole} {a}/{b}'

def camel_case_join(words):
    if not words:
        return ''
    return words[0] + ''.join(w.capitalize() for w in words[1:])

def render_row_left(cells, widths):
    padded = [c.ljust(w) for c, w in zip(cells, widths)]
    return ' | '.join(padded)

def render_row_right(cells, widths):
    padded = [c.rjust(w) for c, w in zip(cells, widths)]
    return ' | '.join(padded)

def render_row_mixed(cells, widths, aligns):
    parts = []
    for c, w, a in zip(cells, widths, aligns):
        if a == 'l':
            parts.append(c.ljust(w))
        elif a == 'r':
            parts.append(c.rjust(w))
        else:
            parts.append(c.center(w))
    return ' '.join(parts)

def render_grid_row(cells, widths):
    padded = [c.ljust(w) for c, w in zip(cells, widths)]
    return '| ' + ' | '.join(padded) + ' |'

def render_row_with_sep(cells, widths, sep):
    padded = [c.ljust(w) for c, w in zip(cells, widths)]
    return sep.join(padded)

def render_row_truncate_pad(cells, widths):
    parts = []
    for c, w in zip(cells, widths):
        if len(c) > w:
            parts.append(c[:w])
        else:
            parts.append(c.ljust(w))
    return ' '.join(parts)

def render_two_col_table(pairs, key_width):
    lines = [k.ljust(key_width) + str(v) for k, v in pairs]
    return '\n'.join(lines)

def wrap_greedy(text, width):
    words = text.split()
    if not words:
        return []
    lines = []
    current = words[0]
    for word in words[1:]:
        if len(current) + 1 + len(word) <= width:
            current += ' ' + word
        else:
            lines.append(current)
            current = word
    lines.append(current)
    return lines
